param([switch]$Force)
$ErrorActionPreference = "Stop"

# Run this from the ROOT of your NaijaDrops checkout (the folder with package.json).
if (-not (Test-Path -LiteralPath "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from the root of your NaijaDrops checkout." -ForegroundColor Red
    exit 1
}

function Get-NormalizedHash {
    param([string]$path, [bool]$binary)
    $bytes = [System.IO.File]::ReadAllBytes($path)
    if (-not $binary) {
        $text = [System.Text.Encoding]::UTF8.GetString($bytes).TrimStart([char]0xFEFF) -replace "`r`n", "`n"
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($text)
    }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    return (($sha.ComputeHash($bytes) | ForEach-Object { $_.ToString("x2") }) -join "")
}

Write-Host ""
Write-Host "=== Location disclosure, Wake Lock on active delivery, hardware Back button closes overlays ===" -ForegroundColor Cyan

$items = @(
    @{ Path = "src/utils/locationDisclosure.js"; Label = "NEW: prominent in-app location disclosure (Play policy)"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/utils/geolocation.js"; Label = "Show the disclosure before the first location prompt"; Binary = $false; Sha = "b25f1f98ab88c761821fca92632c3fc2bf67adef73100cacd1b473cfedbc50d2"; B64 = "" },
    @{ Path = "src/utils/useWakeLock.js"; Label = "NEW: keep the screen awake hook"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/utils/useBackToClose.js"; Label = "NEW: Back button closes overlays hook"; Binary = $false; Sha = ""; B64 = "" },
    @{ Path = "src/app/rider/(main)/active-job/page.jsx"; Label = "Keep the screen awake during an active delivery"; Binary = $false; Sha = "0a0ff52f390fc57a7daca2213dbd58613f73779dc54304dc35dd7c9a7122da5f"; B64 = "" },
    @{ Path = "src/components/MapModal.jsx"; Label = "Back button closes the map picker"; Binary = $false; Sha = "9cc35690edfef38ca44314271f3062b46b8c827b223dd180757b9e62d146668d"; B64 = "" },
    @{ Path = "src/components/ReviewModal.jsx"; Label = "Back button closes the review sheet"; Binary = $false; Sha = "7419fb7823cd9dc9600b0bba44bc0ceb1cfa6cd761fa00740385192aea1a4c44"; B64 = "" },
    @{ Path = "src/components/rider/IncomingOrderCard.jsx"; Label = "Back button closes the enlarged package photo"; Binary = $false; Sha = "3581386884e0ce2fa58a144105221bae314915f23d5e76c36113105c8229c418"; B64 = "" },
    @{ Path = "src/components/OrderChat.jsx"; Label = "Back button closes the chat sheet"; Binary = $false; Sha = "0ff811cd46b11d0fc554a03b1373cb34d6b745fd20f22b8aa760484fd57ac633"; B64 = "" }
)

# Preflight: refuse to overwrite a file you have changed since this patch was prepared.
$changed = @()
foreach ($it in $items) {
    if ((Test-Path -LiteralPath $it.Path) -and $it.Sha) {
        if ((Get-NormalizedHash -path $it.Path -binary $it.Binary) -ne $it.Sha) { $changed += $it.Path }
    }
}
if ($changed.Count -gt 0 -and -not $Force) {
    Write-Host "STOPPED - these files differ from the version this patch was built against:" -ForegroundColor Yellow
    $changed | ForEach-Object { Write-Host "  $_" -ForegroundColor Yellow }
    Write-Host "Nothing was changed. If you are sure, re-run with -Force (backups are still written)." -ForegroundColor Yellow
    exit 2
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
foreach ($it in $items) {
    $full = Join-Path (Get-Location).Path $it.Path
    Write-Host "Writing: $($it.Path)" -ForegroundColor Cyan
    Write-Host "  $($it.Label)"
    if (Test-Path -LiteralPath $full) {
        $backup = "$full.$timestamp.bak"
        Copy-Item -LiteralPath $full -Destination $backup -Force
        Write-Host "  Backup: $backup" -ForegroundColor Yellow
    } else {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $full) | Out-Null
    }
    [System.IO.File]::WriteAllBytes($full, [System.Convert]::FromBase64String($it.B64))
    Write-Host "  Done." -ForegroundColor Green
}
Write-Host ""
Write-Host "Finished: $($items.Count) file(s)." -ForegroundColor Green
